#include <bits/stdc++.h>
using namespace std;

int main() {
    double cx, cy, r;
    double x1, y1, x2, y2;

    cin >> cx >> cy >> r;
    cin >> x1 >> y1 >> x2 >> y2;

    // Direction vector of line
    double dx = x2 - x1;
    double dy = y2 - y1;
    double len = sqrt(dx*dx + dy*dy);
    double udx = dx/len, udy = dy/len;

    // Vector from (x1,y1) to center
    double fx = cx - x1;
    double fy = cy - y1;

    // Project onto line direction
    double t = fx*udx + fy*udy;

    // Foot of perpendicular
    double footx = x1 + t*udx;
    double footy = y1 + t*udy;

    // Distance from center to line
    double distx = cx - footx;
    double disty = cy - footy;
    double dist2 = distx*distx + disty*disty;
    double r2 = r*r;

    vector<pair<double,double>> pts;

    if (dist2 > r2 + 1e-9) {
        // No intersection
    } else if (dist2 > r2 - 1e-9) {
        // Tangent
        pts.push_back({footx, footy});
    } else {
        double half = sqrt(r2 - dist2);
        pts.push_back({footx - half*udx, footy - half*udy});
        pts.push_back({footx + half*udx, footy + half*udy});
    }

    // Sort by x, then y
    sort(pts.begin(), pts.end());

    cout << fixed << setprecision(4);
    for (auto& p : pts) {
        cout << p.first << " " << p.second << "\n";
    }

    return 0;
}

