using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double cx, cy, r, x1, y1, x2, y2;
    cin >> cx >> cy >> r >> x1 >> y1 >> x2 >> y2;

    // Shift so circle center is at origin
    x1 -= cx; y1 -= cy;
    x2 -= cx; y2 -= cy;

    double dx = x2 - x1;
    double dy = y2 - y1;
    double dr2 = dx * dx + dy * dy;
    double D = x1 * y2 - x2 * y1;

    double disc = r * r * dr2 - D * D;
    if (disc < -1e-9) {
        cout << "none\n";
        return 0;
    }

    if (fabs(disc) < 1e-9) {
        double ix = D * dy / dr2;
        double iy = -D * dx / dr2;
        ix += cx;
        iy += cy;
        cout << fixed << setprecision(10) << ix << " " << iy << "\n";
    } else {
        double sqrt_disc = sqrt(disc);
        double sign_dy = (dy < 0) ? -1.0 : 1.0;
        if (fabs(dy) < 1e-9) sign_dy = 1.0;

        double ix1 = (D * dy + sign_dy * dx * sqrt_disc) / dr2;
        double iy1 = (-D * dx + fabs(dy) * sqrt_disc) / dr2;
        double ix2 = (D * dy - sign_dy * dx * sqrt_disc) / dr2;
        double iy2 = (-D * dx - fabs(dy) * sqrt_disc) / dr2;

        ix1 += cx; iy1 += cy;
        ix2 += cx; iy2 += cy;

        // Sort by x, then by y
        if (ix1 > ix2 + 1e-12 || (fabs(ix1 - ix2) < 1e-12 && iy1 > iy2 + 1e-12)) {
            swap(ix1, ix2);
            swap(iy1, iy2);
        }

        cout << fixed << setprecision(10) << ix1 << " " << iy1 << "\n";
        cout << ix2 << " " << iy2 << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double cx, cy, r;
    double x1, y1, x2, y2;

    cin >> cx >> cy >> r;
    cin >> x1 >> y1 >> x2 >> y2;

    // Translate so the circle center is at the origin.
    double ax = x1 - cx, ay = y1 - cy;
    double bx = x2 - cx, by = y2 - cy;

    // Direction vector of the line.
    double dx = bx - ax, dy = by - ay;

    // Projection of origin onto the line: P = A + t * d
    double dd = dx * dx + dy * dy;
    double t = -(ax * dx + ay * dy) / dd;

    double px = ax + t * dx;
    double py = ay + t * dy;

    // Distance from projection point to each intersection along the line.
    double dist2 = px * px + py * py;
    double len = sqrt(max(0.0, r * r - dist2));
    double dnorm = sqrt(dd);

    double ux = dx / dnorm, uy = dy / dnorm;

    double ix1 = px + ux * len;
    double iy1 = py + uy * len;
    double ix2 = px - ux * len;
    double iy2 = py - uy * len;

    // Translate back.
    ix1 += cx; iy1 += cy;
    ix2 += cx; iy2 += cy;

    // Output in lexicographical order (x, then y).
    pair<double, double> p1 = {ix1, iy1}, p2 = {ix2, iy2};
    if (p2 < p1) swap(p1, p2);

    cout << fixed << setprecision(10);
    cout << p1.first << " " << p1.second << "\n";
    cout << p2.first << " " << p2.second << "\n";

    return 0;
}

#include <stdio.h>
#include <math.h>

int main() {
    double cx, cy, r;
    double x1, y1, x2, y2;

    scanf("%lf %lf %lf", &cx, &cy, &r);
    scanf("%lf %lf %lf %lf", &x1, &y1, &x2, &y2);

    double dx = x2 - x1;
    double dy = y2 - y1;

    double fx = x1 - cx;
    double fy = y1 - cy;

    double a = dx*dx + dy*dy;
    double b = 2.0*(fx*dx + fy*dy);
    double c = fx*fx + fy*fy - r*r;

    double disc = b*b - 4.0*a*c;

    if (disc < 0) {
        // No intersection
        printf("No intersection\n");
    } else if (fabs(disc) < 1e-9) {
        double t = -b / (2.0*a);
        double px = x1 + t*dx;
        double py = y1 + t*dy;
        printf("%.4f %.4f\n", px, py);
    } else {
        double t1 = (-b - sqrt(disc)) / (2.0*a);
        double t2 = (-b + sqrt(disc)) / (2.0*a);
        double p1x = x1 + t1*dx;
        double p1y = y1 + t1*dy;
        double p2x = x1 + t2*dx;
        double p2y = y1 + t2*dy;
        // Sort by x, then y
        if (p1x > p2x + 1e-9 || (fabs(p1x-p2x) < 1e-9 && p1y > p2y)) {
            double tmp;
            tmp = p1x; p1x = p2x; p2x = tmp;
            tmp = p1y; p1y = p2y; p2y = tmp;
        }
        printf("%.4f %.4f\n%.4f %.4f\n", p1x, p1y, p2x, p2y);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

int main() {
    double cx, cy, r, a, b, c;
    scanf("%lf %lf %lf", &cx, &cy, &r);
    scanf("%lf %lf %lf", &a, &b, &c);

    // Tolerance for floating point comparison
    const double eps = 1e-9;

    if (fabs(b) < eps) {
        // Vertical line: a*x + c = 0
        double x = -c / a;
        double dx = x - cx;
        double disc = r*r - dx*dx;
        if (disc < -eps) {
            // No intersection
            printf("none\n");
        } else if (disc < eps) {
            // Tangent, one point
            double y = cy;
            printf("(%.3f,%.3f)\n", x, y);
        } else {
            double sqrt_disc = sqrt(disc);
            double y1 = cy - sqrt_disc;
            double y2 = cy + sqrt_disc;
            if (y1 < y2) {
                printf("(%.3f,%.3f)\n(%.3f,%.3f)\n", x, y1, x, y2);
            } else {
                printf("(%.3f,%.3f)\n(%.3f,%.3f)\n", x, y2, x, y1);
            }
        }
    } else {
        // Non-vertical line: y = -(a*x + c)/b
        double A = a*a + b*b;
        double B = 2*a*c + 2*a*b*cy - 2*b*b*cx;
        double C = c*c + 2*b*c*cy + b*b*(cx*cx + cy*cy - r*r);
        // Actually better derive directly:
        // y = -(a x + c)/b
        // Substitute into (x-cx)^2 + (y-cy)^2 = r^2
        // Let m = -a/b, d = -c/b
        double m = -a / b;
        double d = -c / b;
        // y = m*x + d
        // (x-cx)^2 + (m*x + d - cy)^2 = r^2
        double A2 = 1 + m*m;
        double B2 = -2*cx + 2*m*(d - cy);
        double C2 = cx*cx + (d - cy)*(d - cy) - r*r;

        double disc = B2*B2 - 4*A2*C2;
        if (disc < -eps) {
            printf("none\n");
        } else if (disc < eps) {
            double x = -B2 / (2*A2);
            double y = m*x + d;
            printf("(%.3f,%.3f)\n", x, y);
        } else {
            double sqrt_disc = sqrt(disc);
            double x1 = (-B2 - sqrt_disc) / (2*A2);
            double x2 = (-B2 + sqrt_disc) / (2*A2);
            double y1 = m*x1 + d;
            double y2 = m*x2 + d;
            // Sort by x, then y if x equal
            if (x1 < x2 - eps) {
                printf("(%.3f,%.3f)\n(%.3f,%.3f)\n", x1, y1, x2, y2);
            } else if (x2 < x1 - eps) {
                printf("(%.3f,%.3f)\n(%.3f,%.3f)\n", x2, y2, x1, y1);
            } else {
                // x equal, sort by y
                if (y1 < y2) {
                    printf("(%.3f,%.3f)\n(%.3f,%.3f)\n", x1, y1, x2, y2);
                } else {
                    printf("(%.3f,%.3f)\n(%.3f,%.3f)\n", x2, y2, x1, y1);
                }
            }
        }
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double cx, cy, r;
    double x1, y1, x2, y2;

    if (scanf("%lf %lf %lf", &cx, &cy, &r) != 3) return 0;
    if (scanf("%lf %lf %lf %lf", &x1, &y1, &x2, &y2) != 4) return 0;

    /* Direction vector of the line */
    double dx = x2 - x1;
    double dy = y2 - y1;

    /* Project circle center onto the line */
    double vx = cx - x1;
    double vy = cy - y1;
    double len2 = dx * dx + dy * dy;

    double t = (vx * dx + vy * dy) / len2;
    double px = x1 + t * dx;
    double py = y1 + t * dy;

    /* Distance from projection point to each intersection along the line */
    double dist2 = (px - cx) * (px - cx) + (py - cy) * (py - cy);
    double h = sqrt(fmax(0.0, r * r - dist2));

    double len = sqrt(len2);
    double ux = dx / len;
    double uy = dy / len;

    double ax = px - ux * h;
    double ay = py - uy * h;
    double bx = px + ux * h;
    double by = py + uy * h;

    /* Output in lexicographical order */
    if (ax > bx || (fabs(ax - bx) < 1e-10 && ay > by)) {
        double tmp;
        tmp = ax; ax = bx; bx = tmp;
        tmp = ay; ay = by; by = tmp;
    }

    printf("%.10f %.10f %.10f %.10f\n", ax, ay, bx, by);
    return 0;
}

import java.util.Scanner;

public class CircleLineIntersection {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        double cx = sc.nextDouble();
        double cy = sc.nextDouble();
        double r = sc.nextDouble();
        double a = sc.nextDouble();
        double b = sc.nextDouble();
        double c = sc.nextDouble();

        sc.close();

        double x1, y1, x2, y2;

        if (Math.abs(b) > 1e-9) {
            // y = (-a*x - c) / b
            double A = a * a + b * b;
            double B = 2 * a * c + 2 * a * b * cy - 2 * b * b * cx;
            double C = c * c + 2 * b * c * cy + b * b * (cx * cx + cy * cy - r * r);

            double disc = B * B - 4 * A * C;
            if (disc < 0) {
                // No intersection
                return;
            }
            disc = Math.sqrt(disc);
            x1 = (-B + disc) / (2 * A);
            x2 = (-B - disc) / (2 * A);
            y1 = (-a * x1 - c) / b;
            y2 = (-a * x2 - c) / b;
        } else {
            // b == 0: line is vertical x = -c/a
            double x0 = -c / a;
            double dx = x0 - cx;
            double disc = r * r - dx * dx;
            if (disc < 0) {
                return;
            }
            disc = Math.sqrt(disc);
            x1 = x0;
            x2 = x0;
            y1 = cy + disc;
            y2 = cy - disc;
        }

        // Sort points: by x then y
        if (x1 > x2 || (Math.abs(x1 - x2) < 1e-9 && y1 > y2)) {
            double tmp = x1; x1 = x2; x2 = tmp;
            tmp = y1; y1 = y2; y2 = tmp;
        }

        System.out.printf("%.10f %.10f%n", x1, y1);
        System.out.printf("%.10f %.10f%n", x2, y2);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextDouble();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        double cx = fs.nextDouble();
        double cy = fs.nextDouble();
        double r = fs.nextDouble();
        int q = fs.nextInt();

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < q; i++) {
            double x1 = fs.nextDouble();
            double y1 = fs.nextDouble();
            double x2 = fs.nextDouble();
            double y2 = fs.nextDouble();

            double dx = x2 - x1;
            double dy = y2 - y1;

            // Project center C onto line P1 + t*d
            double t = ((cx - x1) * dx + (cy - y1) * dy) / (dx * dx + dy * dy);
            double fx = x1 + t * dx;
            double fy = y1 + t * dy;

            double dist2 = (fx - cx) * (fx - cx) + (fy - cy) * (fy - cy);
            double h = Math.sqrt(Math.max(0.0, r * r - dist2));

            double dlen = Math.sqrt(dx * dx + dy * dy);
            double ux = dx / dlen;
            double uy = dy / dlen;

            double ax = fx - ux * h;
            double ay = fy - uy * h;
            double bx = fx + ux * h;
            double by = fy + uy * h;

            // Output in lexicographical order
            if (ax > bx || (Math.abs(ax - bx) < 1e-10 && ay > by)) {
                double tmp;
                tmp = ax; ax = bx; bx = tmp;
                tmp = ay; ay = by; by = tmp;
            }

            sb.append(String.format(Locale.US, "%.10f %.10f %.10f %.10f%n", ax, ay, bx, by));
        }

        System.out.print(sb.toString());
    }
}
